import { MakeLogicType, actions, kea, path, reducers } from 'kea'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface conversationsSendOnEnterLogicValues {
    sendOnEnter: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface conversationsSendOnEnterLogicActions {
    setSendOnEnter: (enabled: boolean) => {
        enabled: boolean
    }
}

export type conversationsSendOnEnterLogicType = MakeLogicType<
    conversationsSendOnEnterLogicValues,
    conversationsSendOnEnterLogicActions
>

// Browser-local choice of send shortcut for the ticket composer. Cmd/Ctrl+Enter always sends;
// this decides whether plain Enter sends too, or stays a line break.
export const conversationsSendOnEnterLogic = kea<conversationsSendOnEnterLogicType>([
    path(['products', 'conversations', 'frontend', 'scenes', 'settings', 'conversationsSendOnEnterLogic']),
    actions({
        setSendOnEnter: (enabled: boolean) => ({ enabled }),
    }),
    reducers({
        sendOnEnter: [
            true,
            { persist: true, storageKey: 'conversations_send_reply_on_enter' },
            {
                setSendOnEnter: (_, { enabled }) => enabled,
            },
        ],
    }),
])
